script:
// Spinner (ds-metrics §9 — Android Loader.kt; the iOS DS has none): a 25% ring of `color` with a head segment,
// spinning 360° every 1100 ms (autoplay timeline, forever). Stroke = size / 6.4 (5pt at the default 32).
// No partial-arc primitive, so the head is a short capsule riding the top of the ring.
param size: number = 32
param color: color = @color.accentPrimary
let stroke = size / 6.4
